public static UPSPriceMarginComponentSetup find(UPSPriceComponentCodeRecId _priceComponentCodeRecId, boolean _update = false)
{
    UPSPriceMarginComponentSetup         priceMarginCompSetup;

    if(_update)
    {
        priceMarginCompSetup.selectForUpdate(_update);
    }

    select firstonly priceMarginCompSetup
        where priceMarginCompSetup.PriceComponentCode == _priceComponentCodeRecId;

    return priceMarginCompSetup;
}

public display Description PriCompDescription()
{
    return this.upSPriceComponentCode().Description;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(UPSPriceMarginComponentSetup, PostInLedger):
            if (this.PostInLedger == NoYes::Yes)
            {
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, PostingProfile)).mandatory(true);
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, PostingProfile)).allowEdit(true);
            }
            else
            {
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, PostingProfile)).mandatory(false);
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, PostingProfile)).allowEdit(false);
                this.PostingProfile = "";
            }
            break;
        case fieldNum(UPSPriceMarginComponentSetup, Flexible):
            if (this.Flexible == NoYes::Yes)
            {
                this.CalculationSequence = 0;
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CalculationSequence)).mandatory(false);
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CalculationSequence)).allowEdit(false);

                this.CompoundcalculationBasis = NoYes::No;
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CompoundcalculationBasis)).allowEdit(false);
            }
            else
            {
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CalculationSequence)).mandatory(true);
                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CalculationSequence)).allowEdit(true);

                this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CompoundcalculationBasis)).allowEdit(true);
            }
            break;
        case fieldNum(UPSPriceMarginComponentSetup, CalculationSequence):
            this.validationField();
            break;
    }
}

public void initValue()
{

    super();

    FormObjectSet formObjectSet = this.dataSource();

    if  (formObjectSet != null)
    {
        this.PostInLedger = NoYes::No;
        this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, PostingProfile)).mandatory(false);
        this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, PostingProfile)).allowEdit(false);

        this.Flexible = NoYes::No;
        this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CalculationSequence)).mandatory(true);
        this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CalculationSequence)).allowEdit(true);
        this.dataSource().object(fieldNum(UPSPriceMarginComponentSetup, CompoundcalculationBasis)).allowEdit(true);
    }
}

public static boolean existCalcSequence(UPSCalculationSequenceNum _calcSequence)
{
    return (select firstonly CalculationSequence from UPSPriceMarginComponentSetup
               where UPSPriceMarginComponentSetup.CalculationSequence == _calcSequence).CalculationSequence;
}

public boolean validationField()
{
    UPSPriceMarginComponentSetup priceMarginComponentSetupOrig;
    boolean isEqual;
    boolean ret;

    if (this.CalculationSequence > 0 && this.Flexible == NoYes::No)
    {
        if (this.isNewRecord())
        {
            if (UPSPriceMarginComponentSetup::existCalcSequence(this.CalculationSequence))
            {
                ret = checkFailed(strFmt("@UnifiedPricingService:UPSCalculationCompoundError", this.CalculationSequence));
                this.CalculationSequence = 0;
            }
        }
        else
        {
            priceMarginComponentSetupOrig  = this.orig();

            if (priceMarginComponentSetupOrig.CalculationSequence != this.CalculationSequence && this.CalculationSequence > 0)
            {
                if (UPSPriceMarginComponentSetup::existCalcSequence(this.CalculationSequence))
                {
                    ret = checkFailed(strFmt("@UnifiedPricingService:UPSCalculationCompoundError", this.CalculationSequence));
                    this.CalculationSequence = 0;
                }
            }
        }
    }

    return ret;
}

public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if (this.PostInLedger == NoYes::No && this.PostingProfile != "")
    {
        ret = checkFailed(strFmt("@UnifiedPricingService:UPSPostingProfileValidation", this.PostingProfile, this.PostInLedger));
    }

    if (this.Flexible == NoYes::Yes)
    {
        if (this.CalculationSequence > 0)
        {
            ret = checkFailed(strFmt("@UnifiedPricingService:UPSCalculationSequenceValidation'", this.Flexible));
        }

        if (this.CompoundcalculationBasis == NoYes::Yes)
        {
            ret = checkFailed(strFmt("@UnifiedPricingService:UPSCompoundCalculationBasisValidation", this.Flexible));
        }
    }

    ret = this.validationField();

    return ret;
}
